import org.apache.tika.sax.BasicContentHandlerFactory;
import org.apache.tika.parser.ParseContext;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.UnsupportedEncodingException;
import java.nio.charset.Charset;

import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

@ExtendWith(MockitoExtension.class)
public class BasicContentHandlerFactoryTest {

    @Mock
    private OutputStream outputStream;

    @Mock
    private Charset charset;

    @Mock
    private ParseContext parseContext;

    private BasicContentHandlerFactory factory;

    @BeforeEach
    public void setUp() {
        factory = new BasicContentHandlerFactory();
    }

    @Test
    public void testCreateHandlerWithDefaultValues() throws UnsupportedEncodingException {
        ContentHandler handler = factory.createHandler(outputStream, charset);
        verify(factory, times(1)).createHandlerInner(outputStream, charset);
        assertNotNull(handler);
    }

    @Test
    public void testCreateHandlerWithWriteLimit() throws UnsupportedEncodingException {
        factory.setWriteLimit(100);
        ContentHandler handler = factory.createHandler(outputStream, charset);
        verify(factory, times(1)).createHandlerInner(outputStream, charset);
        assertNotNull(handler);
    }

    @Test
    public void testCreateHandlerWithThrowOnWriteLimitReached() throws UnsupportedEncodingException {
        factory.setThrowOnWriteLimitReached(false);
        factory.setParseContext(parseContext);
        ContentHandler handler = factory.createHandler(outputStream, charset);
        verify(factory, times(1)).createHandlerInner(outputStream, charset);
        assertNotNull(handler);
    }

    @Test
    public void testCreateHandlerWithInvalidParseContext() {
        factory.setThrowOnWriteLimitReached(false);
        assertThrows(IllegalArgumentException.class, () -> factory.setParseContext(null));
    }

    @Test
    public void testCreateHandlerWithUnsupportedCharset() throws UnsupportedEncodingException {
        when(charset.name()).thenReturn("unsupportedCharset");
        assertThrows(RuntimeException.class, () -> factory.createHandler(outputStream, charset));
    }

    @Test
    public void testCreateHandlerWithIgnoreType() throws UnsupportedEncodingException {
        factory.setType(BasicContentHandlerFactory.HANDLER_TYPE.IGNORE);
        ContentHandler handler = factory.createHandler(outputStream, charset);
        verify(factory, times(1)).createHandlerInner(outputStream, charset);
        assertTrue(handler instanceof BasicContentHandlerFactory.NoOpContentHandler);
    }

